286	// =====================================================================
287	// RPC CONTRACTS — exact signatures Dato implements in SQL
288	// =====================================================================
289	// Each RPC has: name, args interface, return type.
290	// SQL function name MATCHES the constant string literal `RPC.<NAME>`.
291	// SQL parameter names MATCH camelCase → snake_case translation:
292	//   args.studioId → p_studio_id (Postgres convention).
293	// Drift between this file and SQL is a P0 bug — Sage scans match.
294	
295	export const RPC = {
296	  WEBHOOK_EVENT_INSERT: 'webhook_event_insert',
297	  STRIPE_CONNECTED_ACCOUNT_CREATE: 'stripe_connected_account_create',
298	  STRIPE_CONNECTED_ACCOUNT_UPDATE_FROM_WEBHOOK: 'stripe_connected_account_update_from_webhook',
299	  STRIPE_CHARGE_RECORD: 'stripe_charge_record',
300	  STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK: 'stripe_charge_update_status_from_webhook',
301	  COMMISSION_SPLIT_RECORD: 'commission_split_record',
302	  COMMISSION_SPLIT_REVERSE: 'commission_split_reverse',
303	  STRIPE_DISPUTE_RECORD: 'stripe_dispute_record',
304	  STRIPE_DISPUTE_UPDATE_STATUS_FROM_WEBHOOK: 'stripe_dispute_update_status_from_webhook',
305	  DISPUTE_DEFENSE_PACK_RECORD: 'dispute_defense_pack_record',
306	  TAX_REMITTANCE_ACCRUE: 'tax_remittance_accrue',
307	  TAX_REMITTANCE_FILE: 'tax_remittance_file',
308	  NEC_1099_EXPORT_RECORD: 'nec_1099_export_record',
309	  // S15 — Connect onboarding capability gates
310	  STUDIO_L2_PAYMENTS_ENABLED: 'studio_l2_payments_enabled',
311	  ARTIST_L2_PAYOUTS_ENABLED: 'artist_l2_payouts_enabled',
312	  // S16 — Deposit pool SAGA (atomic with PaymentIntent lifecycle)
313	  APPLY_DEPOSIT_TO_SESSION: 'apply_deposit_to_session',
314	  CONFIRM_DEPOSIT_APPLICATION: 'confirm_deposit_application',
315	  ROLLBACK_DEPOSIT_APPLICATION: 'rollback_deposit_application',
316	  RELEASE_DEPOSIT_FROM_SESSION: 'release_deposit_from_session',
317	  // S17 — Per-tax-line attribution + reconciliation drift checks
318	  COMMISSION_SPLIT_TAX_LINE_RECORD: 'commission_split_tax_line_record',
319	  COMMISSION_SPLITS_DRIFT_CHECK: 'commission_splits_drift_check',
320	  // S18 — Refund proportional reversal extended to tax_lines + tip routing modes
321	  COMMISSION_SPLIT_TAX_LINE_REVERSE: 'commission_split_tax_line_reverse',
322	  TAX_REMITTANCE_RELEASE: 'tax_remittance_release',
323	} as const;
324	
325	// ---------- commission_split_tax_line_record (S17) ----------
326	
327	/**
328	 * Insert a tax-attribution row for an existing parent commission split.
329	 * One parent split can have N tax-line children (multi-jurisdiction: state + county + city).
330	 *
331	 * Idempotent on (parent_split_id, tax_line_id) UNIQUE — webhook replay safe.
332	 *
333	 * Caller flow: on payment_intent.succeeded webhook, after recording the parent split,
334	 * iterate Stripe charge.amount_details.tax_breakdown[] and insert one tax-line child
335	 * per breakdown entry. Total tax_amount_cents on parent = sum of children.
336	 */
337	export interface CommissionSplitTaxLineRecordArgs {
338	  parentSplitId: string;
339	  taxLineId: string;                  // Stripe tax_line_xxx OR synthetic if Stripe doesn't provide
340	  jurisdiction: string;               // 'US-NY-NYC', 'GB', etc.
341	  taxAmountCents: CentsAmount;
342	}
343	export type CommissionSplitTaxLineRecordResult = { id: string; created: boolean };
344	
345	// ---------- commission_splits_drift_check (S17) ----------
346	
347	/**
348	 * Reconciliation cron query: detect commission split drift.
349	 * Returns lists of PI ids missing their commission_splits row, AND
350	 * disputes that closed lost without a corresponding reversal row.
351	 *
352	 * Read-only — caller (cron) decides what to do (log + alert vs auto-repair).
353	 */
354	export interface CommissionSplitsDriftCheckArgs {
355	  sinceTimestamp: string;             // ISO timestamptz; only check rows created since
356	}
357	export type CommissionSplitsDriftCheckResult = {
358	  pis_missing_split: Array<{ payment_intent_id: string; charge_id: string | null; studio_id: string; created_at: string }>;
359	  disputes_missing_reversal: Array<{ dispute_id: string; charge_id: string; studio_id: string; resolved_at: string | null }>;
360	  // Sage S17 H1 fix — Leg 3: succeeded charges with tax_amount_cents > 0 but no kind='tax_line' children.
361	  // Detects silent loss of tax_line attribution → quarterly remittance miscount.
362	  charges_missing_tax_line: Array<{ payment_intent_id: string; charge_id: string | null; studio_id: string; tax_amount_cents: CentsAmount }>;
363	  // S18 Leg 4: refunds that reversed parent split but missed tax_line proportional reversal.
364	  // Detects under-reversed tax accrual → tax remittance ledger stays accrued for already-refunded amounts.
365	  refunds_missing_tax_reversal: Array<{ refund_id: string; payment_intent_id: string; studio_id: string; missing_jurisdictions: string[] }>;
366	};
367	
368	// ---------- commission_split_tax_line_reverse (S18) ----------
369	
370	/**
371	 * Refund-driven reversal of a tax_line attribution row.
372	 *
373	 * Inserts a NEW commission_splits row with kind='reversal' and parent_split_id
374	 * pointing at the tax_line row being reversed. Negative tax_amount_cents
375	 * indicates the reversal direction.
376	 *
377	 * Idempotent on (parent_tax_line_split_id, refund_id) — replay safe.
378	 *
379	 * Caller flow: refund route reads all kind='tax_line' children for the
380	 * original parent split, then for each child calls this RPC with proportional
381	 * release_tax_cents. The release_cents must satisfy:
382	 *   release_cents <= parent.tax_amount_cents - sum(prior reversals)
383	 */
384	export interface CommissionSplitTaxLineReverseArgs {
385	  parentTaxLineSplitId: string;       // the kind='tax_line' row id being reversed
386	  releaseTaxCents: CentsAmount;       // amount to reverse (positive; RPC stores negative)
387	  refundId: string;                   // Stripe re_xxx for cross-reference + idempotency
388	  idempotencyKey: InkosIdempotencyKey;
389	}
390	export type CommissionSplitTaxLineReverseResult = {
391	  reversal_id: string;
392	  total_reversed_cents: CentsAmount;  // running total reversed against parent tax_line
393	  created: boolean;                    // false on idempotent replay
394	};
395	
396	// ---------- tax_remittance_release (S18) ----------
397	
398	/**
399	 * Refund-driven re-credit of tax accrued in tax_remittance_ledger.
400	 *
401	 * Decrements amount_collected_cents on the matching (studio, location, jurisdiction, period)
402	 * row. NEVER goes negative — RAISE EXCEPTION if release exceeds collected.
403	 *
404	 * Idempotent on idempotency_key (refund-scoped). Replay returns existing release record.
405	 *
406	 * Counterpart to TAX_REMITTANCE_ACCRUE — pair is symmetric for ledger correctness.
407	 */
408	export interface TaxRemittanceReleaseArgs {
409	  studioId: string;
410	  locationId: string;
411	  jurisdiction: string;
412	  period: string;
413	  releaseAmountCents: CentsAmount;
414	  idempotencyKey: InkosIdempotencyKey;
415	  refundId: string;
416	}
417	export type TaxRemittanceReleaseResult = {
418	  ledger_id: string;
419	  new_collected_cents: CentsAmount;
420	  released_cents: CentsAmount;
421	};
