// 6. Destination account + effective application fee.
//
// When the artist has their own Connect account: transfer destination is the artist's
// account; Stripe distributes the commission split in real-time.
//
// When the artist has NOT opted into direct payouts (null): destination is the studio's
// account. Studio keeps 100% of base; payroll distributes the artist's share out-of-band.
// We set effectiveApplicationFee to baseAmountCents so the entire base stays on the platform
// (no automatic transfer to artist).
//
// S18 — tip routing modes:
//   'artist': tip flows to the artist's destination account via destination charge (default).
//   'studio': tip is added to application_fee_amount, keeping it on the platform/studio account.
//             Studio runs a distribution cron (S20+) to split the tip pool per their own rule.
const tipDestination: 'studio' | 'artist' = args.tipPoolEnabled ? 'studio' : 'artist'

const destinationAccount = args.artistConnectedAccountId ?? args.studioConnectedAccountId

// INVARIANT 4: application_fee_amount is ALWAYS set (never undefined).
const effectiveApplicationFee: CentsAmount = (() => {
  if (args.artistConnectedAccountId === null) {
    // No artist Connect account — studio receives everything (base + tip via destination=studio).
    // Payroll distributes artist share out-of-band.
    return (args.baseAmountCents + args.tipAmountCents) as CentsAmount
  }
  if (tipDestination === 'studio') {
    // Tip pool mode — tip flows to studio (added to application_fee); base split as commission.
    // Studio distributes pooled tips later via S20+ cron.
    return (applicationFeeCents + args.tipAmountCents) as CentsAmount
  }
  // Default (tipDestination === 'artist'): tip flows to artist via destination charge.
  // application_fee carries only the studio's commission on the base amount.
  return applicationFeeCents
})()

