/**
 * PATCH /api/settings/payments/tip-pool
 *
 * Owner/admin-only endpoint: toggle the studio's tip routing mode.
 *
 * Auth:  owner | admin (receptionists and artists cannot change this setting).
 * Rate:  authedRatelimit (60 req/min per IP).
 *
 * Body:  { enabled: boolean }
 *
 * Flow:
 *   1. Auth + studio role check (owner/admin only).
 *   2. Rate limit.
 *   3. Zod body validation.
 *   4. Read current value for audit delta.
 *   5. Update studios.tip_pool_enabled via service-role client (RLS restricts direct write).
 *   6. Audit log: tip_pool_mode_changed.
 *   7. Return 200 { tip_pool_enabled: boolean }.
 *
 * Success:    200 { tip_pool_enabled: boolean }
 * Forbidden:  403 { error }
 * Validation: 400 { error, issues }
 * Server err: 500 { error }
 */

import type { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const ALLOWED_ROLES = ['owner', 'admin'] as const
type AllowedRole = typeof ALLOWED_ROLES[number]

// ---------------------------------------------------------------------------
// Input schema
// ---------------------------------------------------------------------------

const TipPoolBodySchema = z.object({
  enabled: z.boolean(),
})

type TipPoolBody = z.infer<typeof TipPoolBodySchema>

// ---------------------------------------------------------------------------
// Route handler
// ---------------------------------------------------------------------------

export async function PATCH(req: NextRequest) {
  // 1. Rate limit
  const ip = getClientIp(req)
  const { success: rateLimitOk } = await authedRatelimit.limit(ip)
  if (!rateLimitOk) {
    return Response.json({ error: 'Rate limited' }, { status: 429 })
  }

  // 2. Auth — session-scoped client
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // 3. Resolve studio membership + role (owner/admin only)
  const { data: member, error: memberErr } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()

  if (memberErr || !member) {
    return Response.json({ error: 'No active studio membership' }, { status: 403 })
  }

  const role = member.role as string
  if (!(ALLOWED_ROLES as readonly string[]).includes(role)) {
    return Response.json(
      { error: 'Only studio owners and admins can change tip routing.' },
      { status: 403 },
    )
  }

  const studioId: string = member.studio_id

  // 4. Parse + validate body
  let body: TipPoolBody
  try {
    const raw = await req.json()
    body = TipPoolBodySchema.parse(raw)
  } catch (err) {
    if (err instanceof z.ZodError) {
      return Response.json({ error: 'Validation failed', issues: err.issues }, { status: 400 })
    }
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  // 5. Read current value for audit delta
  // §S13.3 — tip_pool_enabled column added by Track C migration; cast through unknown.
  const { data: currentRow, error: readErr } = await supabase
    .from('studios')
    .select('tip_pool_enabled')
    .eq('id', studioId)
    .single()

  if (readErr) {
    logger.error({ studio_id: studioId, err: readErr }, 'tip-pool: failed to read current value')
    return Response.json({ error: 'Failed to read current tip routing setting.' }, { status: 500 })
  }

  const currentEnabled =
    (currentRow as unknown as { tip_pool_enabled: boolean | null }).tip_pool_enabled === true

  // 6. Update via service-role client (bypass RLS for this settings write)
  const serviceSupabase = createServiceRoleClient()
  const { error: updateErr } = await serviceSupabase
    .from('studios')
    .update({ tip_pool_enabled: body.enabled } as Record<string, boolean>)
    .eq('id', studioId)

  if (updateErr) {
    logger.error(
      { studio_id: studioId, enabled: body.enabled, err: updateErr },
      'tip-pool: failed to update studios.tip_pool_enabled',
    )
    return Response.json({ error: 'Failed to update tip routing setting.' }, { status: 500 })
  }

  // 7. Audit log (non-fatal)
  await logAuditAction(
    user.id,
    'tip_pool_mode_changed',
    { type: 'studio', id: studioId },
    {
      from: currentEnabled,
      to: body.enabled,
      by: user.id,
      role: role as AllowedRole,
    },
    studioId,
  )

  logger.info(
    { studio_id: studioId, from: currentEnabled, to: body.enabled, user_id: user.id },
    'tip pool mode changed',
  )

  return Response.json({ tip_pool_enabled: body.enabled })
}

'use client'

/**
 * TipPoolToggle
 *
 * Owner/admin setting: choose how tips are routed at charge time.
 *
 *   Direct to artist — tip flows immediately to the artist's connected account
 *                      via destination charge (default for most studios).
 *   Studio pool       — tip flows to studio account; distributed via payout rule (S20+).
 *
 * PATCHes /api/settings/payments/tip-pool on Save.
 * Editorial brand voice — no exclamations, Bone/Onyx/Stone/Rust palette only.
 */

import { useState, useTransition } from 'react'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import { Label } from '@/components/ui/label'
import { Button } from '@/components/ui/button'
import { useToast } from '@/components/ui/use-toast'
import { cn } from '@/lib/utils'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

type TipMode = 'artist' | 'studio'

interface TipPoolToggleProps {
  initialEnabled: boolean
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function TipPoolToggle({ initialEnabled }: TipPoolToggleProps) {
  const [selected, setSelected] = useState<TipMode>(initialEnabled ? 'studio' : 'artist')
  const [isPending, startTransition] = useTransition()
  const { toast } = useToast()

  // Dirty: user changed selection from the server-fetched initial state
  const initialMode: TipMode = initialEnabled ? 'studio' : 'artist'
  const isDirty = selected !== initialMode

  function handleSave() {
    startTransition(async () => {
      try {
        const res = await fetch('/api/settings/payments/tip-pool', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ enabled: selected === 'studio' }),
        })

        if (!res.ok) {
          const json = (await res.json()) as { error?: string }
          toast({
            variant: 'destructive',
            title: 'Could not update tip routing.',
            description: json.error ?? 'An unexpected error occurred.',
          })
          return
        }

        toast({
          description: 'Tip routing updated.',
        })
      } catch {
        toast({
          variant: 'destructive',
          title: 'Could not update tip routing.',
          description: 'Check your connection and try again.',
        })
      }
    })
  }

  return (
    <div
      className={cn(
        'rounded-xl border border-border/60 bg-card p-6 space-y-5',
        'shadow-[var(--shadow-soft)]',
      )}
    >
      {/* Section header */}
      <div className="space-y-1">
        <h2 className="font-serif italic text-[15px] font-normal leading-snug text-foreground">
          How are tips routed?
        </h2>
        <p className="text-xs text-muted-foreground">
          Applies to every in-studio charge from this point forward. Prior charges are unaffected.
        </p>
      </div>

      {/* Radio options */}
      <RadioGroup
        value={selected}
        onValueChange={(val) => setSelected(val as TipMode)}
        className="space-y-3"
      >
        {/* Direct to artist */}
        <div
          className={cn(
            'flex items-start gap-3 rounded-lg border p-4 transition-colors',
            selected === 'artist'
              ? 'border-foreground/30 bg-background'
              : 'border-border/50 bg-background/50',
          )}
        >
          <RadioGroupItem
            value="artist"
            id="tip-route-artist"
            className="mt-0.5 shrink-0"
          />
          <Label
            htmlFor="tip-route-artist"
            className="cursor-pointer space-y-0.5"
          >
            <span className="block text-[13px] font-semibold text-foreground">
              Direct to artist
            </span>
            <span className="block text-xs text-muted-foreground">
              Each tip flows to the artist who took the booking. Standard for most studios.
            </span>
          </Label>
        </div>

        {/* Studio pool */}
        <div
          className={cn(
            'flex items-start gap-3 rounded-lg border p-4 transition-colors',
            selected === 'studio'
              ? 'border-foreground/30 bg-background'
              : 'border-border/50 bg-background/50',
          )}
        >
          <RadioGroupItem
            value="studio"
            id="tip-route-studio"
            className="mt-0.5 shrink-0"
          />
          <Label
            htmlFor="tip-route-studio"
            className="cursor-pointer space-y-0.5"
          >
            <span className="block text-[13px] font-semibold text-foreground">
              Studio pool
            </span>
            <span className="block text-xs text-muted-foreground">
              Tips flow to your studio account. You distribute them later via a payout rule.
            </span>
          </Label>
        </div>
      </RadioGroup>

      {/* Save */}
      <div className="pt-1">
        <Button
          size="sm"
          disabled={!isDirty || isPending}
          onClick={handleSave}
          className="min-w-[80px]"
        >
          {isPending ? 'Saving…' : 'Save'}
        </Button>
      </div>
    </div>
  )
}

